 9→/// Embedded templates directory.
10→static TEMPLATES_DIR: Dir<'_> = include_dir!("$CARGO_MANIFEST_DIR/templates");
11→
12→/// Load the built-in registry manifest.
13→pub fn load_manifest() -> Result<RegistryManifest> {
14→    let manifest_file = TEMPLATES_DIR.get_file("registry.yml").ok_or_else(|| {
15→        crate::error::BivvyError::ConfigNotFound {
16→            path: "templates/registry.yml".into(),
17→        }
18→    })?;
19→
20→    let content = manifest_file.contents_utf8().ok_or_else(|| {
21→        crate::error::BivvyError::ConfigParseError {
22→            path: "templates/registry.yml".into(),
23→            message: "Invalid UTF-8".to_string(),
24→        }
25→    })?;
26→
27→    serde_yaml::from_str(content).map_err(|e| crate::error::BivvyError::ConfigParseError {
28→        path: "templates/registry.yml".into(),
29→        message: e.to_string(),
30→    })
31→}
32→
33→/// Load all built-in templates.
34→pub fn load_templates() -> Result<HashMap<String, Template>> {
35→    let mut templates = HashMap::new();
36→    load_templates_from_dir(&TEMPLATES_DIR, "steps", &mut templates)?;
37→    Ok(templates)
38→}
39→
40→fn load_templates_from_dir(
41→    dir: &Dir<'_>,
42→    prefix: &str,
43→    templates: &mut HashMap<String, Template>,
44→) -> Result<()> {
45→    let steps_dir = dir.get_dir(prefix);
46→
47→    if let Some(steps) = steps_dir {
48→        for entry in steps.dirs() {
49→            // Each subdirectory is a category (ruby, node, common, etc.)
50→            for file in entry.files() {
51→                if let Some(ext) = file.path().extension() {
52→                    if ext == "yml" || ext == "yaml" {
53→                        if let Some(content) = file.contents_utf8() {
54→                            let template: Template =
55→                                serde_yaml::from_str(content).map_err(|e| {
56→                                    crate::error::BivvyError::ConfigParseError {
57→                                        path: file.path().to_path_buf(),
58→                                        message: e.to_string(),
59→                                    }
60→                                })?;
61→                            templates.insert(template.name.clone(), template);
62→                        }
63→                    }
64→                }
65→            }
66→        }
67→    }
68→
69→    Ok(())
70→}
71→
72→/// Check if a template exists in built-ins.
