261→mod tests {
262→    use super::*;
263→    use crate::registry::template::TemplateStep;
264→
265→    fn make_template() -> Template {
266→        Template {
267→            name: "test".to_string(),
268→            description: "Test template".to_string(),
269→            category: "test".to_string(),
270→            version: "1.0.0".to_string(),
271→            min_bivvy_version: None,
272→            platforms: vec![],
273→            detects: vec![],
274→            inputs: HashMap::new(),
275→            step: TemplateStep {
