    #[test]
    fn resolved_step_includes_precondition() {
        let config = StepConfig {
            command: Some("echo test".to_string()),
            precondition: Some(crate::config::CompletedCheck::CommandSucceeds {
                command: "exit 0".to_string(),
            }),
